```python
def generate_magic_grid(n):
    grid = [[0] * n for _ in range(n)]
    num = 0

    for i in range(n):
        for j in range(n):
            grid[i][j] = num
            num += 1

    for i in range(0, n, 4):
        for j in range(0, n, 4):
            # Extract a 4x4 subgrid
            subgrid = [
                [grid[i + x][j + y] for y in range(4)]
                for x in range(4)
            ]
            # Rotate the subgrid 90 degrees
            rotated_subgrid = [
                [subgrid[3 - y][x] for y in range(4)]
                for x in range(4)
            ]
            # Place the rotated subgrid back into the grid
            for x in range(4):
                for y in range(4):
                    grid[i + x][j + y] = rotated_subgrid[x][y]

    return grid

